/* @autogenerated */
package net.civeira.phylax.common.infrastructure.audit;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.mockito.ArgumentMatchers.anyString;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

import java.sql.Connection;
import java.sql.PreparedStatement;
import java.sql.SQLException;
import java.sql.Timestamp;
import java.time.ZonedDateTime;
import java.util.HashMap;
import java.util.Map;

import javax.sql.DataSource;

import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.ArgumentCaptor;

import com.fasterxml.jackson.core.type.TypeReference;
import com.fasterxml.jackson.databind.ObjectMapper;

@DisplayName("AuditWriteService")
class AuditWriteServiceUnitTest {
  private static final ZonedDateTime WHEN = ZonedDateTime.parse("2026-01-02T03:04:05Z");

  private final ObjectMapper mapper = new ObjectMapper();
  private DataSource dataSource;
  private PreparedStatement ps;
  private AuditWriteService service;

  @BeforeEach
  void setUp() throws SQLException {
    dataSource = mock(DataSource.class);
    Connection conn = mock(Connection.class);
    ps = mock(PreparedStatement.class);
    when(dataSource.getConnection()).thenReturn(conn);
    when(conn.prepareStatement(anyString())).thenReturn(ps);
    service = new AuditWriteService(dataSource, mapper);
  }

  private Map<String, String> json(String value) throws Exception {
    return mapper.readValue(value, new TypeReference<Map<String, String>>() {});
  }

  @Test
  @DisplayName("Should store only the values that changed")
  void shouldStoreOnlyDifferences() throws Exception {
    // Arrange — an update changing, adding, removing and keeping values
    Map<String, String> old = new HashMap<>(Map.of("name", "a", "removed", "x", "same", "s"));
    Map<String, String> updated = new HashMap<>(Map.of("name", "b", "added", "y", "same", "s"));
    AuditEvent event = AuditEvent.builder().operation("update").usecase("rename").traceId("t")
        .spanId("s").entityId("e-1").oldValue(old).newValue(updated).performedBy("u").tenant("acme")
        .timestamp(WHEN).sourceRequest("/r").remoteAddress("1.2.3.4").remoteApplication("app")
        .remoteDevice("dev").claims(Map.of("sub", "u")).build();

    // Act — record the event
    service.record("_audit", event);

    // Assert — unchanged values are dropped from both sides
    ArgumentCaptor<String> values = ArgumentCaptor.forClass(String.class);
    verify(ps).setString(eq(6), values.capture());
    verify(ps).setString(eq(7), values.capture());
    assertEquals(Map.of("name", "a", "removed", "x"), json(values.getAllValues().get(0)));
    assertEquals(Map.of("name", "b", "added", "y"), json(values.getAllValues().get(1)));
    verify(ps).setString(2, "update");
    verify(ps).setTimestamp(10, Timestamp.from(WHEN.toInstant()));
    verify(ps).setString(16, "s");
    verify(ps).executeUpdate();
  }

  @Test
  @DisplayName("Should treat missing old and new values as empty")
  void shouldTreatMissingValuesAsEmpty() throws SQLException {
    service.record("_audit", AuditEvent.builder().operation("delete").timestamp(WHEN).build());

    verify(ps).setString(6, "{}");
    verify(ps).setString(7, "{}");
    verify(ps).executeUpdate();
  }

  @Test
  @DisplayName("Should wrap any storage error")
  void shouldWrapStorageErrors() throws SQLException {
    when(dataSource.getConnection()).thenThrow(new SQLException("down"));

    assertThrows(RuntimeException.class,
        () -> service.record("_audit", AuditEvent.builder().timestamp(WHEN).build()));
  }
}
